const staticData = $getWorkflowStaticData('global');
const oldState = staticData.state || {};
staticData.state = { pending_tasks: [], in_progress: null, completed: [] };
return { 
  reset: true, 
  cleared_pending: oldState.pending_tasks?.length || 0,
  cleared_in_progress: oldState.in_progress?.task?.task_id || null
};

   const staticData = $getWorkflowStaticData('global');
   if (!staticData.state) {
     staticData.state = { pending_tasks: [], in_progress: null, completed: [] };
   }
   const state = staticData.state;

   // Parse incoming task list
   const input = $input.first().json;
   const listData = input.body || input;
   const tasks = listData.tasks || [];
   const listId = listData.update_list_id || 'unknown';
   const trigger = listData.trigger || {};

   if (!tasks.length) {
     return { action: 'none', reason: 'no_tasks' };
   }

   // STALE TASK RECOVERY: Clear in_progress if stuck for > 10 minutes
   if (state.in_progress && state.in_progress.started_at) {
     const startedAt = new Date(state.in_progress.started_at).getTime();
     const tenMinutes = 10 * 60 * 1000;
     if (Date.now() - startedAt > tenMinutes) {
       console.log('Clearing stale in_progress task:', state.in_progress.task?.task_id || 'unknown');
       state.in_progress.status = 'timeout';
       state.in_progress.completed_at = new Date().toISOString();
       state.completed.push(state.in_progress);
       state.in_progress = null;
     }
   }

   // DEDUPLICATION: Skip tasks for documents already in queue or recently completed
   const oneHourAgo = Date.now() - (60 * 60 * 1000);
   const pendingDocs = new Set(state.pending_tasks.map(t => t.task?.document || t.task?.target));
   const recentlyCompletedDocs = new Set(
     state.completed
       .filter(t => new Date(t.completed_at).getTime() > oneHourAgo && t.status === 'completed')
       .map(t => t.task?.document || t.task?.target)
   );
   const inProgressDoc = state.in_progress?.task?.document || state.in_progress?.task?.target;

   let skipped = 0;
   const newTasks = tasks.filter(task => {
     const doc = task.document || task.target;
     if (!doc) return true; // Keep tasks without document
     if (pendingDocs.has(doc)) { skipped++; return false; }
     if (inProgressDoc === doc) { skipped++; return false; }
     if (recentlyCompletedDocs.has(doc)) { skipped++; return false; }
     pendingDocs.add(doc); // Track this doc as pending now
     return true;
   });

   if (skipped > 0) {
     console.log('Skipped', skipped, 'duplicate tasks (already pending or recently completed)');
   }

   if (!newTasks.length) {
     return { action: 'skipped', reason: 'all_duplicates', skipped_count: skipped };
   }

   // Add filtered tasks to pending queue with metadata
   newTasks.forEach(task => {
     state.pending_tasks.push({
       task,
       list_id: listId,
       trigger,
       queued_at: new Date().toISOString()
     });
   });

   console.log('Queued', newTasks.length, 'tasks. Total pending:', state.pending_tasks.length);

   // If nothing in progress, dispatch next task
   if (!state.in_progress) {
     const next = state.pending_tasks.shift();
     if (next) {
       state.in_progress = next;
       state.in_progress.started_at = new Date().toISOString();
       staticData.state = state;
       return { 
          action: 'dispatch',
          should_dispatch: true,
          task: next.task, 
          list_id: next.list_id, 
          trigger: next.trigger 
      };
     }
   }

   staticData.state = state;
   return { 
  action: 'queued', 
  should_dispatch: false,  // ADD THIS
  pending_count: state.pending_tasks.length, 
  skipped_count: skipped 
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.state) {
  staticData.state = { pending_tasks: [], in_progress: null, completed: [] };
}
const state = staticData.state;

// Parse callback data
const input = $input.first().json;
const callbackData = input.body || input;
const taskId = callbackData.task_id;
const status = callbackData.status || 'completed';

console.log('Callback received for task:', taskId, 'status:', status);

// Mark current task as complete
if (state.in_progress) {
  state.in_progress.status = status;
  state.in_progress.completed_at = new Date().toISOString();
  state.completed.push(state.in_progress);
  // Keep only last 20 completed
  if (state.completed.length > 20) state.completed = state.completed.slice(-20);
}
state.in_progress = null;

// Dispatch next task if any pending
const next = state.pending_tasks.shift();
if (next) {
  state.in_progress = next;
  state.in_progress.started_at = new Date().toISOString();
  staticData.state = state;
  return { 
    action: 'dispatch', 
    task: next.task, 
    list_id: next.list_id, 
    trigger: next.trigger,
    pending_remaining: state.pending_tasks.length
  };
}

staticData.state = state;
return { action: 'done', message: 'All tasks completed', completed_count: state.completed.length };

const staticData = $getWorkflowStaticData('global');
const state = staticData.state || { pending_tasks: [], in_progress: null, completed: [] };
return {
  status: 'ok',
  pending_count: state.pending_tasks?.length || 0,
  pending_tasks: state.pending_tasks?.map(t => ({
    task_id: t.task?.task_id,
    document: t.task?.document,
    queued_at: t.queued_at
  })) || [],
  in_progress: state.in_progress ? {
    task_id: state.in_progress.task?.task_id,
    document: state.in_progress.task?.document,
    started_at: state.in_progress.started_at
  } : null,
  completed_count: state.completed?.length || 0,
  recent_completed: (state.completed || []).slice(-5).map(t => ({
    task_id: t.task?.task_id,
    status: t.status,
    completed_at: t.completed_at
  })),
  timestamp: new Date().toISOString()
};
